#!/usr/bin/env python3
"""Vendor DWD's own ramp for the radar layer.

The map's rain colours come from DWD's raster, and what they mean is DWD's to state. A ramp
redrawn from memory, or labelled with rates copied out of a blog post, would be a false legend
under a real image — so the legend is DWD's own, asked for as data:

    test/fixtures/make-radar-legend.py            # regenerate qml/Legend.js
    test/fixtures/make-radar-legend.py --probe    # print the ramp, write nothing

GeoServer answers GetLegendGraphic as image/png (a 100x390 white plate, which sits badly on a
dark map) and as application/json — the same ramp as labels and colours, which is what this
uses so the legend can be drawn in the theme's own font.

One trap: the JSON's `quantity` is the raster's own normalised value, *not* mm/h — the 0.1-0.2
band carries 0.017 — so only the `label` and `color` are read. Radar data: Deutscher
Wetterdienst, CC BY 4.0 (the map's credit line already says so).
"""

from __future__ import annotations

import argparse
import json
import sys
import urllib.request
from pathlib import Path

WMS = "https://maps.dwd.de/geoserver/dwd/wms"
LAYER = "dwd:Niederschlagsradar"
URL = (
    f"{WMS}?SERVICE=WMS&VERSION=1.1.1&REQUEST=GetLegendGraphic"
    f"&LAYER={LAYER}&FORMAT=application/json"
)

REPO = Path(__file__).resolve().parents[2]
OUT = REPO / "qml" / "Legend.js"

HEADER = """// DWD's own ramp for the radar layer, generated by test/fixtures/make-radar-legend.py.
//
// Do not edit by hand: re-run the script if the map's colours and the legend ever disagree.
// The labels are DWD's (mm/h bands); the `quantity` their JSON carries beside each one is the
// raster's own normalised value, not a rate, so it is deliberately not here. Source: Deutscher
// Wetterdienst, CC BY 4.0.
"""


def fetch(url: str, timeout: int = 90) -> dict:
    request = urllib.request.Request(url, headers={"User-Agent": "rustybui/0.1"})
    with urllib.request.urlopen(request, timeout=timeout) as response:
        if response.status != 200:
            raise SystemExit(f"{url} answered HTTP {response.status}")
        return json.loads(response.read().decode("utf-8"))


def colormap(document: dict) -> list[dict]:
    for legend in document.get("Legend", []):
        for rule in legend.get("rules", []):
            for symbolizer in rule.get("symbolizers", []):
                entries = symbolizer.get("Raster", {}).get("colormap", {}).get("entries")
                if entries:
                    return entries
    raise SystemExit("the legend JSON carried no raster colormap")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--probe", action="store_true", help="print the ramp, write nothing")
    args = parser.parse_args()

    rows = colormap(fetch(URL))
    ramp: list[dict[str, str]] = []
    no_data: dict[str, str] | None = None
    for row in rows:
        label, colour = row.get("label", ""), row.get("color", "")
        if not colour:
            continue
        opacity = float(row.get("opacity", "1"))
        # A fully transparent entry is the raster's own "nothing here" and would draw as a blank
        # chip; the partly transparent grey one is what DWD paints where it has no data at all.
        if opacity == 0.0:
            continue
        if opacity < 1.0:
            no_data = {"label": label, "color": colour}
            continue
        ramp.append({"label": label, "color": colour})

    print(f"{LAYER}: {len(ramp)} bands, no-data {no_data}")
    for band in ramp:
        print("   %-16s %s" % (band["label"], band["color"]))

    if args.probe:
        return 0

    lines = [HEADER, 'var TITLE = "mm/h";', ""]
    if no_data:
        lines.append("var NO_DATA = %s;" % json.dumps(no_data, ensure_ascii=False))
        lines.append("")
    lines.append("var RAMP = [")
    lines.append(",\n".join("  " + json.dumps(band, ensure_ascii=False) for band in ramp))
    lines.append("];")
    lines.append("")
    OUT.write_text("\n".join(lines))
    print(f"wrote {OUT.relative_to(REPO)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
